def is_magical(n):
    digits = str(n)
    products = set()
    for i in range(1, 1 << len(digits)):
        product = 1
        for j in range(len(digits)):
            if i & (1 << j):
                product *= int(digits[j])
        products.add(product)
    return sum(products) % 2 == 0

def find_kth_magical_number(K):
    count = 0
    num = 0
    while True:
        if is_magical(num):
            count += 1
            if count == K:
                return num
        num += 1

def main():
    T = int(input())
    results = []
    for _ in range(T):
        K = int(input())
        results.append(find_kth_magical_number(K))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
